/**
 * 势力存续年表（factionId → 起止年）。
 *
 * 🔴 2026-11-04 主人令「势力的时代看大部分年在哪个时间段」：本表是「多数年段」判定的唯一数据源，
 *   只用于审计与人工核对，**不参与运行逻辑**（运行时时代仍取 `FactionEra.ts` 的 `FACTION_ERA`）。
 *
 * 字段：
 *   · start / end：该势力作为独立政治实体（政权/王朝/城邦/部族/部落联盟/苏丹国/汗国）的存续起止年；
 *     公元前为负数；end 取被灭/被并入/改号之年（含该年）；至今存续者 end = null。
 *   · source：史书出处或百科条目（本栏即「史书出处注释」）。
 *   · note：补充说明（多段复国、朝代更替、同名异实等）。
 *   · 史无确载者 start/end 记 null 并在 source 注明「不确定」，**不许编造年份**。
 *
 * 四时代年段（2026-11-03 终定）：古典＝起始–476｜封建＝476–1050｜城堡＝1050–1500｜帝国＝1500–1900（1900 后仍归帝国）。
 * 审计：scratch/audit_era_majority.mts（多数年段 vs FACTION_ERA 逐家比对）。
 */

export interface FactionSpan {
    /** 起始年（公元前为负数）；史无确载 = null */
    start: number | null;
    /** 终止年（含该年）；至今存续 = null */
    end: number | null;
    /** 史书出处 / 百科条目；不确定者注明原因 */
    source: string;
    /** 补充说明（多段复国、朝代更替等） */
    note?: string;
}

